using Ave.Extensions.Documents.Core;
using System;
using System.Collections.Frozen;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;

namespace Ave.Extensions.Documents.Html.Parsing.Tokenizing;

/// <summary>
/// The named character references of the HTML Standard (§13.5): 2 231 names, with and without the semicolon, and the
/// one or two code points each stands for. Read once from the embedded table (generated by
/// <c>tools/generate-html-entities.py</c> from the standard's <c>entities.json</c>).
/// </summary>
internal static class NamedCharacterReferences
{
    private static readonly Lazy<FrozenDictionary<string, string>> Table = new(Load);

    /// <summary>The length of the longest name (<c>CounterClockwiseContourIntegral;</c>, 32 characters).</summary>
    public static int LongestName { get; } = 32;

    /// <summary>The characters a name stands for, or null when it is not in the table.</summary>
    /// <param name="name">The name without the ampersand, with its semicolon if it has one.</param>
    /// <returns>The characters, or null.</returns>
    public static string? Find(string name) => Table.Value.TryGetValue(name, out var characters) ? characters : null;

    /// <summary>
    /// "Consume the maximum number of characters possible, where the consumed characters are one of the identifiers in
    /// the first column of the named character references table" (§13.2.5.78): the longest name that the text starting
    /// at <paramref name="start"/> begins with. At most <see cref="LongestName"/> lookups, so the work per reference is
    /// bounded.
    /// </summary>
    /// <param name="text">The input.</param>
    /// <param name="start">Where the name would start (after the ampersand).</param>
    /// <returns>The length of the longest matching name and its characters, or (0, null).</returns>
    public static (int Length, string? Characters) LongestMatch(string text, int start)
    {
        var available = Math.Min(LongestName, text.Length - start);
        var end = 0;
        while (end < available && (InfraAscii.IsAlphanumeric(text[start + end]) || text[start + end] == ';'))
        {
            end++;
            if (text[start + end - 1] == ';')
            {
                break;
            }
        }

        for (var length = end; length > 0; length--)
        {
            if (Find(text.Substring(start, length)) is { } characters)
            {
                return (length, characters);
            }
        }

        return (0, null);
    }

    private static FrozenDictionary<string, string> Load()
    {
        using var stream = typeof(NamedCharacterReferences).Assembly.GetManifestResourceStream("Ave.Extensions.Documents.Html.Parsing.named-character-references.txt")
            ?? throw new InvalidOperationException("The named character reference table is not embedded in the assembly.");
        using var reader = new StreamReader(stream, Encoding.UTF8);
        var table = new Dictionary<string, string>(StringComparer.Ordinal);
        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0 || line[0] == '#')
            {
                continue;
            }

            var parts = line.Split(' ');
            var characters = new StringBuilder();
            for (var i = 1; i < parts.Length; i++)
            {
                characters.Append(char.ConvertFromUtf32(int.Parse(parts[i], NumberStyles.HexNumber, CultureInfo.InvariantCulture)));
            }

            table.Add(parts[0], characters.ToString());
        }

        return table.ToFrozenDictionary(StringComparer.Ordinal);
    }
}
